-- Pikumi POS: the whole schema for a new, empty Supabase project, in one go.
--
-- Paste all of this into Supabase > SQL Editor and press Run, once. It runs
-- every file in supabase/migrations/ in order and records each one in
-- pos_schema_migrations, as apply_migration.py does, so later migrations
-- run one at a time (or with apply_migration.py) on top of it. It is one
-- transaction: if anything fails, nothing is created.
--
-- Generated by `python apply_migration.py --write-setup` from 0001_pos_transactions.sql to
-- 0015_drop_skuvault.sql; do not edit by hand.

begin;

create table if not exists pos_schema_migrations (name text primary key, applied_at timestamptz not null default now());

-- ===================================================================
-- 0001_pos_transactions.sql
-- ===================================================================
-- POS cash transactions: 0001
--
-- One row per completed sale at the till, one row per line sold. Cash only for
-- now; the payment_method check is the single place to widen when card, gift
-- card or split tenders arrive. Customers are deliberately not modelled.
--
-- Money is numeric(12,2) in the transaction's own currency. Never sum across
-- currencies: a CAD till and a USD till are two reports.
--
-- Applied by pos/apply_migration.py, which records each file here once.

create table if not exists pos_schema_migrations (
  name        text primary key,
  applied_at  timestamptz not null default now()
);

-- Receipt numbers. Sequential and never reused, so a printed receipt can be
-- found again. Starts above the numbers the design prototype showed.
create sequence if not exists pos_transaction_number_seq start with 10001;

create table if not exists pos_transactions (
  id                  uuid primary key default gen_random_uuid(),
  transaction_number  bigint not null unique default nextval('pos_transaction_number_seq'),

  -- Set by the register before it sends. The register queues sales offline and
  -- retries, so a retry of the same sale must not create a second row.
  client_record_id    text unique,

  status              text not null default 'completed'
                      check (status in ('completed', 'inspection', 'refunded', 'void')),

  -- Where and who. Location codes are short text ids (the design uses e.g.
  -- 'stc'); a locations table can be added and referenced later.
  location_id         text not null,
  register_id         text,
  staff_name          text not null,

  currency            char(3) not null check (currency in ('CAD', 'USD', 'EUR')),

  -- Tender. Cash only for now: widen this check to add card / gift / split.
  payment_method      text not null default 'cash' check (payment_method in ('cash')),

  -- Totals, all in `currency`.
  subtotal            numeric(12,2) not null check (subtotal >= 0),
  discount_total      numeric(12,2) not null default 0 check (discount_total >= 0),
  coupon_code         text,
  tax_rate            numeric(7,5)  not null check (tax_rate >= 0 and tax_rate < 1),
  tax_label           text,                       -- e.g. 'HST 13%', printed on the receipt
  tax_total           numeric(12,2) not null default 0 check (tax_total >= 0),
  grand_total         numeric(12,2) not null check (grand_total >= 0),

  -- Inspection orders take a deposit today (the cheapest hairpiece in the
  -- sale) and settle the balance later. amount_paid is what actually changed
  -- hands at this transaction.
  is_inspection       boolean not null default false,
  deposit_total       numeric(12,2) check (deposit_total is null or deposit_total >= 0),
  amount_paid         numeric(12,2) not null check (amount_paid >= 0),

  -- Cash drawer detail. Required whenever payment_method = 'cash'.
  cash_received       numeric(12,2) check (cash_received is null or cash_received >= 0),
  change_given        numeric(12,2) not null default 0 check (change_given >= 0),

  -- Refunds are recorded on the sale they reverse. A partial refund leaves the
  -- status as it was; a full one sets it to 'refunded'.
  refund_amount       numeric(12,2) check (refund_amount is null or refund_amount > 0),
  refund_method       text check (refund_method is null or refund_method in ('cash', 'store_credit')),
  refund_reason       text,
  refund_approved_by  text,
  refunded_at         timestamptz,

  note                text,

  sold_at             timestamptz not null default now(),
  created_at          timestamptz not null default now(),
  updated_at          timestamptz not null default now(),

  constraint pos_transactions_totals_add_up
    check (grand_total = round(subtotal - discount_total + tax_total, 2)),
  constraint pos_transactions_discount_within_subtotal
    check (discount_total <= subtotal),
  constraint pos_transactions_paid_matches_deposit_rule
    check (
      (is_inspection and deposit_total is not null and amount_paid = deposit_total)
      or (not is_inspection and deposit_total is null and amount_paid = grand_total)
    ),
  constraint pos_transactions_cash_detail
    check (
      payment_method <> 'cash'
      or (cash_received is not null
          and cash_received >= amount_paid
          and change_given = round(cash_received - amount_paid, 2))
    ),
  constraint pos_transactions_refund_within_paid
    check (refund_amount is null or refund_amount <= amount_paid),
  constraint pos_transactions_refund_fields_together
    check (
      (refund_amount is null and refund_method is null and refunded_at is null)
      or (refund_amount is not null and refund_method is not null and refunded_at is not null)
    ),
  constraint pos_transactions_refunded_status_needs_refund
    check (status <> 'refunded' or refund_amount is not null)
);

comment on table pos_transactions is
  'One row per POS sale. Cash only for now. Amounts are in the row''s currency; never sum across currencies.';
comment on column pos_transactions.client_record_id is
  'Idempotency key set by the register''s offline queue. A retried send must not create a second row.';
comment on column pos_transactions.amount_paid is
  'What changed hands at this transaction: grand_total, or deposit_total for an inspection order.';
comment on column pos_transactions.change_given is
  'cash_received minus amount_paid. Enforced by check constraint for cash sales.';

create table if not exists pos_transaction_items (
  id              bigint generated always as identity primary key,
  transaction_id  uuid not null references pos_transactions (id) on delete cascade,
  line_no         smallint not null check (line_no > 0),

  -- Product identity is captured as text at the time of sale so a receipt
  -- still reads correctly after a rename or price change. A products table
  -- can be referenced from sku later without changing these rows.
  sku             text not null,
  product_name    text,
  category        text,                    -- men | women | ext | supply | service
  spec            text,                    -- colour / grey / length label as printed, e.g. '#1B Off black · 20% grey'
  grade           text not null default 'std'
                  check (grade in ('std', 'ob', 'os1', 'os2')),   -- standard, open box, off standard good / low

  quantity        integer not null check (quantity > 0),
  unit_price      numeric(12,2) not null check (unit_price >= 0),
  line_total      numeric(12,2) generated always as (round(unit_price * quantity, 2)) stored,
  made_to_order   boolean not null default false,

  unique (transaction_id, line_no)
);

comment on table pos_transaction_items is
  'Lines of a POS sale. unit_price is the price actually charged after any grade discount or option upcharge.';

create index if not exists pos_transactions_sold_at_idx      on pos_transactions (sold_at desc);
create index if not exists pos_transactions_location_day_idx on pos_transactions (location_id, sold_at desc);
create index if not exists pos_transactions_status_idx       on pos_transactions (status);
create index if not exists pos_transaction_items_sku_idx     on pos_transaction_items (sku);
create index if not exists pos_transaction_items_txn_idx     on pos_transaction_items (transaction_id);

-- Keep updated_at honest.
create or replace function pos_set_updated_at() returns trigger
language plpgsql as $$
begin
  new.updated_at := now();
  return new;
end;
$$;

drop trigger if exists pos_transactions_set_updated_at on pos_transactions;
create trigger pos_transactions_set_updated_at
  before update on pos_transactions
  for each row execute function pos_set_updated_at();

-- Cash drawer reconciliation: one line per till, per local day, per currency.
-- Refunds paid back in cash come off the drawer.
create or replace view pos_daily_cash_summary as
select
  location_id,
  currency,
  (sold_at at time zone 'America/Toronto')::date                     as sale_day,
  count(*)                                                           as sales,
  count(*) filter (where is_inspection)                              as inspection_deposits,
  sum(amount_paid)                                                   as amount_paid,
  sum(tax_total)                                                     as tax_total,
  sum(cash_received)                                                 as cash_received,
  sum(change_given)                                                  as change_given,
  sum(refund_amount) filter (where refund_method = 'cash')           as cash_refunded,
  sum(amount_paid)
    - coalesce(sum(refund_amount) filter (where refund_method = 'cash'), 0) as net_cash_in_drawer
from pos_transactions
where status <> 'void'
  and payment_method = 'cash'
group by location_id, currency, (sold_at at time zone 'America/Toronto')::date;

comment on view pos_daily_cash_summary is
  'Per till, per Toronto calendar day, per currency. Use for end-of-day cash counts.';

-- Row Level Security: on, with no policies. Only the service role (server-side
-- code holding the service key) can read or write until policies are added for
-- whatever auth the register ends up using. Default deny is the safe start.
alter table pos_transactions      enable row level security;
alter table pos_transaction_items enable row level security;
insert into pos_schema_migrations (name) values ('0001_pos_transactions.sql') on conflict do nothing;

-- ===================================================================
-- 0002_pos_products.sql
-- ===================================================================
-- POS products: 0002
--
-- The product list for the register, imported from the show-prep Google Sheet
-- by pos/import_products.py. One row per SKU; barcodes live in their own table
-- because several SKUs carry two barcodes (a UPC and an Amazon ASIN, or two
-- UPCs for one product).
--
-- Show prices are whole dollars with tax already included (the sheet's website
-- price is exactly the show price / 1.13), so this migration also teaches
-- pos_transactions about tax-inclusive pricing.

create table if not exists pos_products (
  id                  uuid primary key default gen_random_uuid(),
  sku                 text not null unique,
  name                text not null,
  category            text not null,                -- sheet 类别: CN, KR, US, Clearance

  -- Selling price as shown to the customer. price_includes_tax says whether the
  -- register must add tax on top (false) or back it out for the receipt (true).
  price               numeric(12,2) check (price is null or price >= 0),
  price_includes_tax  boolean not null default true,
  currency            char(3) not null default 'CAD' check (currency in ('CAD', 'USD', 'EUR')),
  cost                numeric(12,2) check (cost is null or cost >= 0),

  -- Stock brought to the show, as counted (sheet 本次展会拿货数量). show_qty is
  -- the parsed number; show_qty_raw keeps markers such as '2+1*' or '*'.
  show_qty            integer,
  show_qty_raw        text,

  is_set              boolean not null default false,   -- sheet Note = 'Set'
  is_clearance        boolean not null default false,   -- sheet 清仓 = TRUE
  is_active           boolean not null default true,    -- sellable at the register
  note                text,

  -- Provenance: the raw sheet row and where it came from.
  sheet               jsonb,
  sheet_row           integer,
  imported_at         timestamptz,

  created_at          timestamptz not null default now(),
  updated_at          timestamptz not null default now()
);

comment on table pos_products is
  'Register product list, one row per SKU, imported from the show-prep sheet. Barcodes are in pos_product_barcodes.';
comment on column pos_products.price is
  'Customer-facing price in `currency`. Tax-inclusive when price_includes_tax; a null price means the item cannot be rung up.';

create index if not exists pos_products_category_idx on pos_products (category);
create index if not exists pos_products_name_idx     on pos_products (lower(name));

create table if not exists pos_product_barcodes (
  barcode     text primary key,                            -- UPC, EAN or ASIN as scanned
  product_id  uuid not null references pos_products (id) on delete cascade,
  created_at  timestamptz not null default now()
);

comment on table pos_product_barcodes is
  'Scannable codes. Many codes may point at one product; one code points at exactly one product.';

create index if not exists pos_product_barcodes_product_idx on pos_product_barcodes (product_id);

drop trigger if exists pos_products_set_updated_at on pos_products;
create trigger pos_products_set_updated_at
  before update on pos_products
  for each row execute function pos_set_updated_at();

-- Sale lines can now point at the product they came from. sku stays as the
-- text captured at the time of sale, so a receipt survives a product rename.
alter table pos_transaction_items
  add column if not exists product_id uuid references pos_products (id),
  add column if not exists barcode    text;

create index if not exists pos_transaction_items_product_idx on pos_transaction_items (product_id);

-- Tax-inclusive sales. When prices_include_tax is true the line prices and
-- subtotal already contain tax; tax_total is the amount backed out for the
-- receipt and does not add to the total.
alter table pos_transactions
  add column if not exists prices_include_tax boolean not null default false;

alter table pos_transactions drop constraint if exists pos_transactions_totals_add_up;
alter table pos_transactions add constraint pos_transactions_totals_add_up check (
  (not prices_include_tax and grand_total = round(subtotal - discount_total + tax_total, 2))
  or (prices_include_tax and grand_total = round(subtotal - discount_total, 2) and tax_total <= grand_total)
);

alter table pos_products         enable row level security;
alter table pos_product_barcodes enable row level security;
insert into pos_schema_migrations (name) values ('0002_pos_products.sql') on conflict do nothing;

-- ===================================================================
-- 0003_pos_users.sql
-- ===================================================================
-- POS users: 0003
--
-- Staff accounts for the register and the admin portal. Each person has a
-- name and a personal PIN (stored hashed, never in clear); admins can also
-- open the admin portal and approve refunds. The first admin is created
-- through the portal using the master code held in Secret Manager.

create table if not exists pos_users (
  id            uuid primary key default gen_random_uuid(),
  name          text not null,
  role          text not null default 'cashier' check (role in ('cashier', 'admin')),
  pin_hash      text not null,                 -- algorithm$salt$hash, see main.py
  is_active     boolean not null default true,
  last_login_at timestamptz,
  created_by    text,
  created_at    timestamptz not null default now(),
  updated_at    timestamptz not null default now()
);

-- Names are how staff pick themselves on the lock screen, so no two active
-- users may share one (case-insensitively).
create unique index if not exists pos_users_active_name_idx on pos_users (lower(name)) where is_active;

comment on table pos_users is
  'Register and admin portal accounts. PINs are salted hashes; role admin opens the portal and approves refunds.';

drop trigger if exists pos_users_set_updated_at on pos_users;
create trigger pos_users_set_updated_at
  before update on pos_users
  for each row execute function pos_set_updated_at();

-- Sales remember which account rang them, alongside the name captured as text.
alter table pos_transactions
  add column if not exists staff_user_id uuid references pos_users (id);

create index if not exists pos_transactions_staff_user_idx on pos_transactions (staff_user_id);

alter table pos_users enable row level security;
insert into pos_schema_migrations (name) values ('0003_pos_users.sql') on conflict do nothing;

-- ===================================================================
-- 0004_remove_tax.sql
-- ===================================================================
-- Remove tax: 0004
--
-- The register sells at the shelf price with no tax handling at all, so the
-- tax columns, the tax-inclusive flag and the tax terms in the totals rule go.
-- What the customer pays is subtotal minus discount.

drop view if exists pos_daily_cash_summary;

alter table pos_transactions drop constraint if exists pos_transactions_totals_add_up;
alter table pos_transactions
  drop column if exists tax_rate,
  drop column if exists tax_label,
  drop column if exists tax_total,
  drop column if exists prices_include_tax;
alter table pos_transactions add constraint pos_transactions_totals_add_up
  check (grand_total = round(subtotal - discount_total, 2));

alter table pos_products drop column if exists price_includes_tax;
comment on column pos_products.price is
  'Customer-facing price in `currency`, exactly as charged. A null price means the item cannot be rung up.';

create or replace view pos_daily_cash_summary as
select
  location_id,
  currency,
  (sold_at at time zone 'America/Toronto')::date                     as sale_day,
  count(*)                                                           as sales,
  count(*) filter (where is_inspection)                              as inspection_deposits,
  sum(amount_paid)                                                   as amount_paid,
  sum(cash_received)                                                 as cash_received,
  sum(change_given)                                                  as change_given,
  sum(refund_amount) filter (where refund_method = 'cash')           as cash_refunded,
  sum(amount_paid)
    - coalesce(sum(refund_amount) filter (where refund_method = 'cash'), 0) as net_cash_in_drawer
from pos_transactions
where status <> 'void'
  and payment_method = 'cash'
group by location_id, currency, (sold_at at time zone 'America/Toronto')::date;

comment on view pos_daily_cash_summary is
  'Per till, per Toronto calendar day, per currency. Use for end-of-day cash counts.';
insert into pos_schema_migrations (name) values ('0004_remove_tax.sql') on conflict do nothing;

-- ===================================================================
-- 0005_pos_events.sql
-- ===================================================================
-- Events: 0005
--
-- An event is a show (or any selling period): a name, a currency and a date
-- range. Sales are tagged with the event they were rung under, the register
-- sells under the event chosen in its header, and Analytics reads one event
-- at a time. location_id on sales stays as the event's code for the drawer
-- view and older rows.

create table if not exists pos_events (
  id          uuid primary key default gen_random_uuid(),
  code        text not null unique,                 -- short id, e.g. esi-montreal-2026; written to sales as location_id
  name        text not null,
  starts_on   date not null,
  ends_on     date not null,
  currency    char(3) not null default 'CAD' check (currency in ('CAD', 'USD', 'EUR')),
  is_active   boolean not null default true,        -- false hides it from the register's selector
  created_by  text,
  created_at  timestamptz not null default now(),
  updated_at  timestamptz not null default now(),
  constraint pos_events_dates check (ends_on >= starts_on)
);

comment on table pos_events is
  'Shows and other selling periods. Sales carry event_id; the register sells under the event selected in its header.';

drop trigger if exists pos_events_set_updated_at on pos_events;
create trigger pos_events_set_updated_at
  before update on pos_events
  for each row execute function pos_set_updated_at();

-- The event the register has been selling under so far.
insert into pos_events (code, name, starts_on, ends_on, currency, created_by)
values ('esi-montreal-2026', 'ESI Montreal 2026', date '2026-09-25', date '2026-09-28', 'CAD', 'migration')
on conflict (code) do nothing;

alter table pos_transactions
  add column if not exists event_id uuid references pos_events (id);

update pos_transactions t set event_id = e.id
from pos_events e
where t.event_id is null and t.location_id = e.code;

create index if not exists pos_transactions_event_sold_idx on pos_transactions (event_id, sold_at desc);

alter table pos_events enable row level security;
insert into pos_schema_migrations (name) values ('0005_pos_events.sql') on conflict do nothing;

-- ===================================================================
-- 0006_pos_venues.sql
-- ===================================================================
-- Venues: 0006
--
-- pos_events now holds two kinds of selling venue: an event (a show, with
-- dates) and a store (a permanent location, with an address). A deployment
-- runs in one mode (POS_MODE = event or store) and only lists venues of that
-- kind. The table keeps its name so existing sales and code are untouched.

alter table pos_events
  add column if not exists kind    text not null default 'event' check (kind in ('event', 'store')),
  add column if not exists address text;

alter table pos_events alter column starts_on drop not null;
alter table pos_events alter column ends_on   drop not null;

alter table pos_events drop constraint if exists pos_events_dates;
alter table pos_events add constraint pos_events_dates check (
  (kind = 'event' and starts_on is not null and ends_on is not null and ends_on >= starts_on)
  or (kind = 'store' and (starts_on is null or ends_on is null or ends_on >= starts_on))
);

comment on table pos_events is
  'Selling venues: events (shows with dates) and stores (permanent locations with an address). Sales carry event_id.';

-- The first real store.
insert into pos_events (code, name, kind, address, currency, created_by)
values ('markham-steeles', 'Markham · 4300 Steeles Ave E', 'store',
        'A1-201, 4300 Steeles Ave E, Markham, ON L3R 0Y5', 'CAD', 'migration')
on conflict (code) do nothing;
insert into pos_schema_migrations (name) values ('0006_pos_venues.sql') on conflict do nothing;

-- ===================================================================
-- 0007_pos_inventory_sync.sql
-- ===================================================================
-- Inventory sync with SkuVault: 0007
--
-- A venue can name the SkuVault warehouse and location that holds its stock.
-- When it does, the register shows on-hand quantities from that location,
-- each sale removes the sold units there, and a full refund adds them back.
-- Every removal or add-back is a row in pos_inventory_moves so a failed call
-- can be retried and audited.

alter table pos_events
  add column if not exists sv_warehouse text,
  add column if not exists sv_location  text;

comment on column pos_events.sv_warehouse is 'SkuVault warehouse code (e.g. IT1) holding this venue''s stock; null = no inventory sync.';
comment on column pos_events.sv_location  is 'SkuVault location code (e.g. PKP) within sv_warehouse.';

create table if not exists pos_inventory_moves (
  id              bigint generated always as identity primary key,
  transaction_id  uuid not null references pos_transactions (id) on delete cascade,
  line_no         smallint not null,
  sku             text not null,
  quantity        integer not null check (quantity > 0),
  direction       text not null check (direction in ('out', 'in')),   -- out = sold, in = refunded
  warehouse       text not null,
  location        text not null,
  status          text not null default 'pending' check (status in ('pending', 'ok', 'failed')),
  attempts        integer not null default 0,
  last_error      text,
  response        jsonb,
  created_at      timestamptz not null default now(),
  updated_at      timestamptz not null default now(),
  done_at         timestamptz,
  unique (transaction_id, line_no, direction)
);

create index if not exists pos_inventory_moves_status_idx on pos_inventory_moves (status, created_at) where status <> 'ok';

alter table pos_inventory_moves enable row level security;

comment on table pos_inventory_moves is
  'One row per sale line sent to SkuVault (out) or added back on refund (in). Retried while status is pending or failed.';

-- The Markham store sells from location PKP in the internal-transfer warehouse.
update pos_events set sv_warehouse = 'IT1', sv_location = 'PKP'
where code = 'markham-steeles' and sv_location is null;
insert into pos_schema_migrations (name) values ('0007_pos_inventory_sync.sql') on conflict do nothing;

-- ===================================================================
-- 0008_pos_card_payments.sql
-- ===================================================================
-- Card payments on a Clover Flex: 0008
--
-- A venue can name the Clover store key and device serial the register
-- charges through (via the company's Clover proxy). A card sale is a
-- pos_transactions row with payment_method = 'card' and no cash detail; the
-- attempt itself, including ones that failed or whose outcome is unknown,
-- is a pos_card_payments row keyed by the register's client record id.

alter table pos_transactions drop constraint if exists pos_transactions_payment_method_check;
alter table pos_transactions add constraint pos_transactions_payment_method_check
  check (payment_method in ('cash', 'card'));

alter table pos_transactions drop constraint if exists pos_transactions_refund_method_check;
alter table pos_transactions add constraint pos_transactions_refund_method_check
  check (refund_method is null or refund_method in ('cash', 'store_credit', 'card'));

alter table pos_events
  add column if not exists clover_store  text,
  add column if not exists clover_device text;

comment on column pos_events.clover_store  is 'Store key the Clover proxy knows this venue by; null = no card payments.';
comment on column pos_events.clover_device is 'Serial number of the Clover Flex at this venue.';

create table if not exists pos_card_payments (
  id                bigint generated always as identity primary key,
  client_record_id  text not null unique,              -- the sale's idempotency key; also the Clover order id
  event_id          uuid references pos_events (id),
  transaction_id    uuid references pos_transactions (id) on delete set null,
  amount            numeric(12,2) not null check (amount > 0),
  currency          char(3) not null,
  store_key         text not null,
  device            text not null,
  staff_name        text,
  status            text not null default 'started'
                    check (status in ('started', 'paid', 'failed', 'unknown')),
  clover_payment_id text,
  message           text,
  response          jsonb,
  cart              jsonb not null,                    -- the lines, discount and note, to record the sale once paid
  created_at        timestamptz not null default now(),
  updated_at        timestamptz not null default now()
);

create index if not exists pos_card_payments_open_idx on pos_card_payments (created_at desc) where status in ('started', 'unknown');

alter table pos_card_payments enable row level security;

comment on table pos_card_payments is
  'One row per card charge sent to the Clover Flex. paid rows point at the sale they became; unknown rows need a status check.';
insert into pos_schema_migrations (name) values ('0008_pos_card_payments.sql') on conflict do nothing;

-- ===================================================================
-- 0009_pos_card_device_optional.sql
-- ===================================================================
-- 0009: the Clover proxy keeps the Flex serial for each store key itself, so
-- a venue only needs the store key; the device is optional and, when blank,
-- resolved from the proxy's roster at charge time.
alter table pos_card_payments alter column device drop not null;
insert into pos_schema_migrations (name) values ('0009_pos_card_device_optional.sql') on conflict do nothing;

-- ===================================================================
-- 0010_pos_sales_tax.sql
-- ===================================================================
-- Sales tax per venue: 0010
--
-- A venue can carry a tax rate and label (the Markham store: HST 13%). Tax is
-- added on top of the shelf price at checkout: grand_total = subtotal -
-- discount_total + tax_total. Venues with no rate keep selling tax-free, so
-- the trade-show register is unchanged until a rate is set on an event.

alter table pos_events
  add column if not exists tax_rate  numeric(7,5) not null default 0 check (tax_rate >= 0 and tax_rate < 1),
  add column if not exists tax_label text;

comment on column pos_events.tax_rate  is 'Sales tax added at checkout as a fraction, e.g. 0.13000 for HST 13%. 0 = no tax.';
comment on column pos_events.tax_label is 'Printed on receipts and invoices, e.g. HST 13%.';

alter table pos_transactions
  add column if not exists tax_rate  numeric(7,5) not null default 0 check (tax_rate >= 0 and tax_rate < 1),
  add column if not exists tax_label text,
  add column if not exists tax_total numeric(12,2) not null default 0 check (tax_total >= 0);

alter table pos_transactions drop constraint if exists pos_transactions_totals_add_up;
alter table pos_transactions add constraint pos_transactions_totals_add_up
  check (grand_total = round(subtotal - discount_total + tax_total, 2));

comment on column pos_transactions.tax_total is 'Tax charged on top of (subtotal - discount_total), at tax_rate, as the venue was set when the sale was rung.';

drop view if exists pos_daily_cash_summary;
create or replace view pos_daily_cash_summary as
select
  location_id,
  currency,
  (sold_at at time zone 'America/Toronto')::date                     as sale_day,
  count(*)                                                           as sales,
  count(*) filter (where is_inspection)                              as inspection_deposits,
  sum(amount_paid)                                                   as amount_paid,
  sum(tax_total)                                                     as tax_total,
  sum(cash_received)                                                 as cash_received,
  sum(change_given)                                                  as change_given,
  sum(refund_amount) filter (where refund_method = 'cash')           as cash_refunded,
  sum(amount_paid)
    - coalesce(sum(refund_amount) filter (where refund_method = 'cash'), 0) as net_cash_in_drawer
from pos_transactions
where status <> 'void'
  and payment_method = 'cash'
group by location_id, currency, (sold_at at time zone 'America/Toronto')::date;

comment on view pos_daily_cash_summary is
  'Per till, per Toronto calendar day, per currency. Use for end-of-day cash counts.';

-- The Markham store charges Ontario HST.
update pos_events set tax_rate = 0.13, tax_label = 'HST 13%' where code = 'markham-steeles';
insert into pos_schema_migrations (name) values ('0010_pos_sales_tax.sql') on conflict do nothing;

-- ===================================================================
-- 0011_pos_line_discounts.sql
-- ===================================================================
-- Line discounts: 0011
--
-- A cart line can carry its own discount (a dollar amount or a percentage,
-- recorded as the dollar amount taken off that line). line_total becomes the
-- line's net: unit_price x quantity - line_discount. The whole-sale discount
-- (discount_total) still applies on top, and subtotal is the sum of net lines.

alter table pos_transaction_items
  add column if not exists line_discount numeric(12,2) not null default 0 check (line_discount >= 0);

alter table pos_transaction_items drop column if exists line_total;
alter table pos_transaction_items
  add column line_total numeric(12,2) generated always as (round(unit_price * quantity - line_discount, 2)) stored;

comment on column pos_transaction_items.line_discount is 'Dollar discount taken off this line before the whole-sale discount.';
comment on column pos_transaction_items.line_total is 'Net for the line: unit_price x quantity - line_discount.';
insert into pos_schema_migrations (name) values ('0011_pos_line_discounts.sql') on conflict do nothing;

-- ===================================================================
-- 0012_pos_fuzzy_search.sql
-- ===================================================================
-- Fuzzy product search: 0012
--
-- The register matches each typed word anywhere in a product's name or SKU,
-- ignoring case, punctuation and word order, and tolerates small typos with
-- pg_trgm's word_similarity. Additive: it installs the extension and changes
-- no data.
create schema if not exists extensions;
create extension if not exists pg_trgm with schema extensions;
insert into pos_schema_migrations (name) values ('0012_pos_fuzzy_search.sql') on conflict do nothing;

-- ===================================================================
-- 0013_pos_product_edits.sql
-- ===================================================================
-- Product edits from the register: 0013
--
-- Any signed-in user can edit a product from the register. The barcode and the SkuVault
-- description are written to SkuVault, the company's catalogue for every
-- channel; name, price and category stay register-only. Each save is logged
-- here with what it changed, by whom, so a barcode change can be traced.
create table if not exists pos_product_edits (
  id          bigint generated always as identity primary key,
  product_id  uuid references pos_products (id) on delete set null,
  sku         text not null,
  changes     jsonb not null,             -- {"field": {"from": ..., "to": ...}, ...}
  skuvault    jsonb,                      -- what was sent to SkuVault and its reply, if anything
  edited_by   text not null,
  edited_at   timestamptz not null default now()
);
create index if not exists pos_product_edits_sku_idx on pos_product_edits (sku, edited_at desc);
alter table pos_product_edits enable row level security;
comment on table pos_product_edits is 'One row per product saved from the register; barcode and description changes also went to SkuVault.';
insert into pos_schema_migrations (name) values ('0013_pos_product_edits.sql') on conflict do nothing;

-- ===================================================================
-- 0014_pos_gift_lines.sql
-- ===================================================================
-- Gift lines: 0014
--
-- A cashier can mark a line as a gift. It is sold at $0 (line_discount equals
-- the full line, so line_total is 0) and still takes the units out of stock;
-- is_gift says why the line is free, for receipts and reporting.
alter table pos_transaction_items
  add column if not exists is_gift boolean not null default false;
comment on column pos_transaction_items.is_gift is 'Given away at $0: line_discount is the whole line. Stock still moves.';
insert into pos_schema_migrations (name) values ('0014_pos_gift_lines.sql') on conflict do nothing;

-- ===================================================================
-- 0015_drop_skuvault.sql
-- ===================================================================
-- Drop SkuVault: 0015
--
-- The register no longer talks to SkuVault. Product photos were read from the
-- SkuVault-synced public.products table; they are now a link on each product,
-- set by the product upload (image_url column) or the register's edit sheet.
-- The inventory-sync queue and the venue's SkuVault warehouse and bin go.

alter table pos_products add column if not exists image_url text;
comment on column pos_products.image_url is 'Link to the product photo shown on the register; null shows a placeholder.';

drop table if exists pos_inventory_moves;
alter table pos_events drop column if exists sv_warehouse, drop column if exists sv_location;
alter table pos_product_edits drop column if exists skuvault;
comment on table pos_product_edits is 'One row per product saved from the register: what changed, by whom.';
insert into pos_schema_migrations (name) values ('0015_drop_skuvault.sql') on conflict do nothing;

commit;
